void SessionIDType_template::set_specific()
{
if (template_selection != SPECIFIC_VALUE) {
template_sel old_selection = template_selection;
clean_up();
single_value = new single_value_struct;
set_selection(SPECIFIC_VALUE);
if (old_selection == ANY_VALUE || old_selection == ANY_OR_OMIT) {
single_value->field_content = ANY_OR_OMIT;
}
}
}

void SessionIDType_template::copy_value(const SessionIDType& other_value)
{
single_value = new single_value_struct;
if (other_value.content().is_bound()) {
  if (other_value.content().ispresent()) single_value->field_content = other_value.content()();
  else single_value->field_content = OMIT_VALUE;
} else {
  single_value->field_content.clean_up();
}
set_selection(SPECIFIC_VALUE);
}

void SessionIDType_template::copy_template(const SessionIDType_template& other_value)
{
switch (other_value.template_selection) {
case SPECIFIC_VALUE:
single_value = new single_value_struct;
if (UNINITIALIZED_TEMPLATE != other_value.content().get_selection()) {
single_value->field_content = other_value.content();
} else {
single_value->field_content.clean_up();
}
case OMIT_VALUE:
case ANY_VALUE:
case ANY_OR_OMIT:
break;
case VALUE_LIST:
case COMPLEMENTED_LIST:
value_list.n_values = other_value.value_list.n_values;
value_list.list_value = new SessionIDType_template[value_list.n_values];
for (unsigned int list_count = 0; list_count < value_list.n_values; list_count++)
value_list.list_value[list_count].copy_template(other_value.value_list.list_value[list_count]);
break;
default:
TTCN_error("Copying an uninitialized/unsupported template of type @SECC_Types.SessionIDType.");
break;
}
set_selection(other_value);
}

