boolean V2GTPHeaderReqType_template::match(const V2GTPHeaderReqType& other_value, boolean legacy) const
{
if (!other_value.is_bound()) return FALSE;
switch (template_selection) {
case ANY_VALUE:
case ANY_OR_OMIT:
return TRUE;
case OMIT_VALUE:
return FALSE;
case SPECIFIC_VALUE:
if(!other_value.protocolVersion().is_bound()) return FALSE;
if(!single_value->field_protocolVersion.match(other_value.protocolVersion(), legacy))return FALSE;
if(!other_value.inverseProtocolVersion().is_bound()) return FALSE;
if(!single_value->field_inverseProtocolVersion.match(other_value.inverseProtocolVersion(), legacy))return FALSE;
if(!other_value.payloadType().is_bound()) return FALSE;
if(!single_value->field_payloadType.match(other_value.payloadType(), legacy))return FALSE;
if(!other_value.payloadLength().is_bound()) return FALSE;
if(!single_value->field_payloadLength.match(other_value.payloadLength(), legacy))return FALSE;
if(!other_value.payload().is_bound()) return FALSE;
if((other_value.payload().ispresent() ? !single_value->field_payload.match((const OCTETSTRING&)other_value.payload(), legacy) : !single_value->field_payload.match_omit(legacy)))return FALSE;
return TRUE;
case VALUE_LIST:
case COMPLEMENTED_LIST:
for (unsigned int list_count = 0; list_count < value_list.n_values; list_count++)
if (value_list.list_value[list_count].match(other_value, legacy)) return template_selection == VALUE_LIST;
return template_selection == COMPLEMENTED_LIST;
default:
TTCN_error("Matching an uninitialized/unsupported template of type @SECC_Types.V2GTPHeaderReqType.");
}
return FALSE;
}

