void V2GTPHeaderReqType_template::log_match(const V2GTPHeaderReqType& match_value, boolean legacy) const
{
if(TTCN_Logger::VERBOSITY_COMPACT == TTCN_Logger::get_matching_verbosity()){
if(match(match_value, legacy)){
TTCN_Logger::print_logmatch_buffer();
TTCN_Logger::log_event_str(" matched");
} else{
if (template_selection == SPECIFIC_VALUE) {
size_t previous_size = TTCN_Logger::get_logmatch_buffer_len();
if(!single_value->field_protocolVersion.match(match_value.protocolVersion(), legacy)){
TTCN_Logger::log_logmatch_info(".protocolVersion");
single_value->field_protocolVersion.log_match(match_value.protocolVersion(), legacy);
TTCN_Logger::set_logmatch_buffer_len(previous_size);
}
if(!single_value->field_inverseProtocolVersion.match(match_value.inverseProtocolVersion(), legacy)){
TTCN_Logger::log_logmatch_info(".inverseProtocolVersion");
single_value->field_inverseProtocolVersion.log_match(match_value.inverseProtocolVersion(), legacy);
TTCN_Logger::set_logmatch_buffer_len(previous_size);
}
if(!single_value->field_payloadType.match(match_value.payloadType(), legacy)){
TTCN_Logger::log_logmatch_info(".payloadType");
single_value->field_payloadType.log_match(match_value.payloadType(), legacy);
TTCN_Logger::set_logmatch_buffer_len(previous_size);
}
if(!single_value->field_payloadLength.match(match_value.payloadLength(), legacy)){
TTCN_Logger::log_logmatch_info(".payloadLength");
single_value->field_payloadLength.log_match(match_value.payloadLength(), legacy);
TTCN_Logger::set_logmatch_buffer_len(previous_size);
}
if (match_value.payload().ispresent()){
if(!single_value->field_payload.match(match_value.payload(), legacy)){
TTCN_Logger::log_logmatch_info(".payload");
single_value->field_payload.log_match(match_value.payload(), legacy);
TTCN_Logger::set_logmatch_buffer_len(previous_size);
}
} else {
if (!single_value->field_payload.match_omit(legacy)){
 TTCN_Logger::log_logmatch_info(".payload := omit with ");
TTCN_Logger::print_logmatch_buffer();
single_value->field_payload.log();
TTCN_Logger::log_event_str(" unmatched");
TTCN_Logger::set_logmatch_buffer_len(previous_size);
}
}
}else {
TTCN_Logger::print_logmatch_buffer();
match_value.log();
TTCN_Logger::log_event_str(" with ");
log();
TTCN_Logger::log_event_str(" unmatched");
}
}
return;
}
if (template_selection == SPECIFIC_VALUE) {
TTCN_Logger::log_event_str("{ protocolVersion := ");
single_value->field_protocolVersion.log_match(match_value.protocolVersion(), legacy);
TTCN_Logger::log_event_str(", inverseProtocolVersion := ");
single_value->field_inverseProtocolVersion.log_match(match_value.inverseProtocolVersion(), legacy);
TTCN_Logger::log_event_str(", payloadType := ");
single_value->field_payloadType.log_match(match_value.payloadType(), legacy);
TTCN_Logger::log_event_str(", payloadLength := ");
single_value->field_payloadLength.log_match(match_value.payloadLength(), legacy);
TTCN_Logger::log_event_str(", payload := ");
if (match_value.payload().ispresent()) single_value->field_payload.log_match(match_value.payload(), legacy);
else {
TTCN_Logger::log_event_str("omit with ");
single_value->field_payload.log();
if (single_value->field_payload.match_omit(legacy)) TTCN_Logger::log_event_str(" matched");
else TTCN_Logger::log_event_str(" unmatched");
}
TTCN_Logger::log_event_str(" }");
} else {
match_value.log();
TTCN_Logger::log_event_str(" with ");
log();
if (match(match_value, legacy)) TTCN_Logger::log_event_str(" matched");
else TTCN_Logger::log_event_str(" unmatched");
}
}

