SDPRequestType::SDPRequestType(const SDPRequestType& other_value)
{
if(!other_value.is_bound()) TTCN_error("Copying an unbound value of type @SECC_Types.SDPRequestType.");
if (other_value.security().is_bound()) field_security = other_value.security();
else field_security.clean_up();
if (other_value.transportProtocol().is_bound()) field_transportProtocol = other_value.transportProtocol();
else field_transportProtocol.clean_up();
}

void SDPRequestType::clean_up()
{
field_security.clean_up();
field_transportProtocol.clean_up();
}

const TTCN_Typedescriptor_t* SDPRequestType::get_descriptor() const { return &SDPRequestType_descr_; }
SDPRequestType& SDPRequestType::operator=(const SDPRequestType& other_value)
{
if (this != &other_value) {
  if(!other_value.is_bound()) TTCN_error("Assignment of an unbound value of type @SECC_Types.SDPRequestType.");
  if (other_value.security().is_bound()) field_security = other_value.security();
  else field_security.clean_up();
  if (other_value.transportProtocol().is_bound()) field_transportProtocol = other_value.transportProtocol();
  else field_transportProtocol.clean_up();
}
return *this;
}

boolean SDPRequestType::operator==(const SDPRequestType& other_value) const
{
return field_security==other_value.field_security
  && field_transportProtocol==other_value.field_transportProtocol;
}

boolean SDPRequestType::is_bound() const
{
return (field_security.is_bound())
  || (field_transportProtocol.is_bound());
}
boolean SDPRequestType::is_value() const
{
return field_security.is_value()
  && field_transportProtocol.is_value();
}
