SDPRequestType_template& SDPRequestType_template::operator=(const SDPRequestType_template& other_value)
{
if (&other_value != this) {
clean_up();
copy_template(other_value);
}
return *this;
}

boolean SDPRequestType_template::match(const SDPRequestType& other_value, boolean legacy) const
{
if (!other_value.is_bound()) return FALSE;
switch (template_selection) {
case ANY_VALUE:
case ANY_OR_OMIT:
return TRUE;
case OMIT_VALUE:
return FALSE;
case SPECIFIC_VALUE:
if(!other_value.security().is_bound()) return FALSE;
if(!single_value->field_security.match(other_value.security(), legacy))return FALSE;
if(!other_value.transportProtocol().is_bound()) return FALSE;
if(!single_value->field_transportProtocol.match(other_value.transportProtocol(), legacy))return FALSE;
return TRUE;
case VALUE_LIST:
case COMPLEMENTED_LIST:
for (unsigned int list_count = 0; list_count < value_list.n_values; list_count++)
if (value_list.list_value[list_count].match(other_value, legacy)) return template_selection == VALUE_LIST;
return template_selection == COMPLEMENTED_LIST;
default:
TTCN_error("Matching an uninitialized/unsupported template of type @SECC_Types.SDPRequestType.");
}
return FALSE;
}

boolean SDPRequestType_template::is_bound() const
{
if (template_selection == UNINITIALIZED_TEMPLATE && !is_ifpresent) return FALSE;
if (template_selection != SPECIFIC_VALUE) return TRUE;
return single_value->field_security.is_bound()

 ||single_value->field_transportProtocol.is_bound()
;
}

boolean SDPRequestType_template::is_value() const
{
if (template_selection != SPECIFIC_VALUE || is_ifpresent) return FALSE;
return single_value->field_security.is_value()
 &&single_value->field_transportProtocol.is_value();
}

void SDPRequestType_template::clean_up()
{
switch (template_selection) {
case SPECIFIC_VALUE:
delete single_value;
break;
case VALUE_LIST:
case COMPLEMENTED_LIST:
delete [] value_list.list_value;
default:
break;
}
template_selection = UNINITIALIZED_TEMPLATE;
}

SDPRequestType SDPRequestType_template::valueof() const
{
if (template_selection != SPECIFIC_VALUE || is_ifpresent)
TTCN_error("Performing a valueof or send operation on a non-specific template of type @SECC_Types.SDPRequestType.");
SDPRequestType ret_val;
if (single_value->field_security.is_bound()) {
ret_val.security() = single_value->field_security.valueof();
}
if (single_value->field_transportProtocol.is_bound()) {
ret_val.transportProtocol() = single_value->field_transportProtocol.valueof();
}
return ret_val;
}

void SDPRequestType_template::set_type(template_sel template_type, unsigned int list_length)
{
if (template_type != VALUE_LIST && template_type != COMPLEMENTED_LIST)
TTCN_error("Setting an invalid list for a template of type @SECC_Types.SDPRequestType.");
clean_up();
set_selection(template_type);
value_list.n_values = list_length;
value_list.list_value = new SDPRequestType_template[list_length];
}

SDPRequestType_template& SDPRequestType_template::list_item(unsigned int list_index) const
{
if (template_selection != VALUE_LIST && template_selection != COMPLEMENTED_LIST)
TTCN_error("Accessing a list element of a non-list template of type @SECC_Types.SDPRequestType.");
if (list_index >= value_list.n_values)
TTCN_error("Index overflow in a value list template of type @SECC_Types.SDPRequestType.");
return value_list.list_value[list_index];
}

