void SDPResponseType::set_implicit_omit()
{
if (seccIpAddress().is_bound()) seccIpAddress().set_implicit_omit();
if (seccPort().is_bound()) seccPort().set_implicit_omit();
if (security().is_bound()) security().set_implicit_omit();
if (transportProtocol().is_bound()) transportProtocol().set_implicit_omit();
}

