struct V2GMessageType_template::single_value_struct {
OCTETSTRING_template field_header;
OCTETSTRING_template field_body;
};

void V2GMessageType_template::set_specific()
{
if (template_selection != SPECIFIC_VALUE) {
template_sel old_selection = template_selection;
clean_up();
single_value = new single_value_struct;
set_selection(SPECIFIC_VALUE);
if (old_selection == ANY_VALUE || old_selection == ANY_OR_OMIT) {
single_value->field_header = ANY_VALUE;
single_value->field_body = ANY_OR_OMIT;
}
}
}

void V2GMessageType_template::copy_value(const V2GMessageType& other_value)
{
single_value = new single_value_struct;
if (other_value.header().is_bound()) {
  single_value->field_header = other_value.header();
} else {
  single_value->field_header.clean_up();
}
if (other_value.body().is_bound()) {
  if (other_value.body().ispresent()) single_value->field_body = other_value.body()();
  else single_value->field_body = OMIT_VALUE;
} else {
  single_value->field_body.clean_up();
}
set_selection(SPECIFIC_VALUE);
}

void V2GMessageType_template::copy_template(const V2GMessageType_template& other_value)
{
switch (other_value.template_selection) {
case SPECIFIC_VALUE:
single_value = new single_value_struct;
if (UNINITIALIZED_TEMPLATE != other_value.header().get_selection()) {
single_value->field_header = other_value.header();
} else {
single_value->field_header.clean_up();
}
if (UNINITIALIZED_TEMPLATE != other_value.body().get_selection()) {
single_value->field_body = other_value.body();
} else {
single_value->field_body.clean_up();
}
case OMIT_VALUE:
case ANY_VALUE:
case ANY_OR_OMIT:
break;
case VALUE_LIST:
case COMPLEMENTED_LIST:
value_list.n_values = other_value.value_list.n_values;
value_list.list_value = new V2GMessageType_template[value_list.n_values];
for (unsigned int list_count = 0; list_count < value_list.n_values; list_count++)
value_list.list_value[list_count].copy_template(other_value.value_list.list_value[list_count]);
break;
default:
TTCN_error("Copying an uninitialized/unsupported template of type @SECC_Types.V2GMessageType.");
break;
}
set_selection(other_value);
}

V2GMessageType_template::V2GMessageType_template()
{
}

V2GMessageType_template::V2GMessageType_template(template_sel other_value)
 : Base_Template(other_value)
{
check_single_selection(other_value);
}

V2GMessageType_template::V2GMessageType_template(const V2GMessageType& other_value)
{
copy_value(other_value);
}

V2GMessageType_template::V2GMessageType_template(const OPTIONAL<V2GMessageType>& other_value)
{
switch (other_value.get_selection()) {
case OPTIONAL_PRESENT:
copy_value((const V2GMessageType&)other_value);
break;
case OPTIONAL_OMIT:
set_selection(OMIT_VALUE);
break;
default:
TTCN_error("Creating a template of type @SECC_Types.V2GMessageType from an unbound optional field.");
}
}

V2GMessageType_template::V2GMessageType_template(const V2GMessageType_template& other_value)
: Base_Template()
{
copy_template(other_value);
}

V2GMessageType_template::~V2GMessageType_template()
{
clean_up();
}

V2GMessageType_template& V2GMessageType_template::operator=(template_sel other_value)
{
check_single_selection(other_value);
clean_up();
set_selection(other_value);
return *this;
}

V2GMessageType_template& V2GMessageType_template::operator=(const V2GMessageType& other_value)
{
clean_up();
copy_value(other_value);
return *this;
}

V2GMessageType_template& V2GMessageType_template::operator=(const OPTIONAL<V2GMessageType>& other_value)
{
clean_up();
switch (other_value.get_selection()) {
case OPTIONAL_PRESENT:
copy_value((const V2GMessageType&)other_value);
break;
case OPTIONAL_OMIT:
set_selection(OMIT_VALUE);
break;
default:
TTCN_error("Assignment of an unbound optional field to a template of type @SECC_Types.V2GMessageType.");
}
return *this;
}

V2GMessageType_template& V2GMessageType_template::operator=(const V2GMessageType_template& other_value)
{
if (&other_value != this) {
clean_up();
copy_template(other_value);
}
return *this;
}

boolean V2GMessageType_template::match(const V2GMessageType& other_value, boolean legacy) const
{
if (!other_value.is_bound()) return FALSE;
switch (template_selection) {
case ANY_VALUE:
case ANY_OR_OMIT:
return TRUE;
case OMIT_VALUE:
return FALSE;
case SPECIFIC_VALUE:
if(!other_value.header().is_bound()) return FALSE;
if(!single_value->field_header.match(other_value.header(), legacy))return FALSE;
if(!other_value.body().is_bound()) return FALSE;
if((other_value.body().ispresent() ? !single_value->field_body.match((const OCTETSTRING&)other_value.body(), legacy) : !single_value->field_body.match_omit(legacy)))return FALSE;
return TRUE;
case VALUE_LIST:
case COMPLEMENTED_LIST:
for (unsigned int list_count = 0; list_count < value_list.n_values; list_count++)
if (value_list.list_value[list_count].match(other_value, legacy)) return template_selection == VALUE_LIST;
return template_selection == COMPLEMENTED_LIST;
default:
TTCN_error("Matching an uninitialized/unsupported template of type @SECC_Types.V2GMessageType.");
}
return FALSE;
}

boolean V2GMessageType_template::is_bound() const
{
if (template_selection == UNINITIALIZED_TEMPLATE && !is_ifpresent) return FALSE;
if (template_selection != SPECIFIC_VALUE) return TRUE;
return single_value->field_header.is_bound()

 ||(single_value->field_body.is_omit() || single_value->field_body.is_bound())
;
}

boolean V2GMessageType_template::is_value() const
{
if (template_selection != SPECIFIC_VALUE || is_ifpresent) return FALSE;
return single_value->field_header.is_value()
 &&(single_value->field_body.is_omit() || single_value->field_body.is_value());
}

void V2GMessageType_template::clean_up()
{
switch (template_selection) {
case SPECIFIC_VALUE:
delete single_value;
break;
case VALUE_LIST:
case COMPLEMENTED_LIST:
delete [] value_list.list_value;
default:
break;
}
template_selection = UNINITIALIZED_TEMPLATE;
}

V2GMessageType V2GMessageType_template::valueof() const
{
if (template_selection != SPECIFIC_VALUE || is_ifpresent)
TTCN_error("Performing a valueof or send operation on a non-specific template of type @SECC_Types.V2GMessageType.");
V2GMessageType ret_val;
if (single_value->field_header.is_bound()) {
ret_val.header() = single_value->field_header.valueof();
}
if (single_value->field_body.is_omit()) ret_val.body() = OMIT_VALUE;
else if (single_value->field_body.is_bound()) {
ret_val.body() = single_value->field_body.valueof();
}
return ret_val;
}

void V2GMessageType_template::set_type(template_sel template_type, unsigned int list_length)
{
if (template_type != VALUE_LIST && template_type != COMPLEMENTED_LIST)
TTCN_error("Setting an invalid list for a template of type @SECC_Types.V2GMessageType.");
clean_up();
set_selection(template_type);
value_list.n_values = list_length;
value_list.list_value = new V2GMessageType_template[list_length];
}

V2GMessageType_template& V2GMessageType_template::list_item(unsigned int list_index) const
{
if (template_selection != VALUE_LIST && template_selection != COMPLEMENTED_LIST)
TTCN_error("Accessing a list element of a non-list template of type @SECC_Types.V2GMessageType.");
if (list_index >= value_list.n_values)
TTCN_error("Index overflow in a value list template of type @SECC_Types.V2GMessageType.");
return value_list.list_value[list_index];
}

